\label{example: LS}
For the least squares estimator ($a=\infty$), we have $g(u, y; b) = (y - u)/(1 + b)$. In this case, $b_*$ can be computed in closed form and \eqref{eq: fixed point state evolution} simplifies to:
\begin{eqnarray}\label{eq: least square fixed point}
    & b_* =\frac{1}{\delta-1}, \qquad \nu_* =E[\sigma'(Z_2)\bar\varepsilon]=0, \qquad 
   & \tau_*^2 = E [(Z_1  + \sigma(Z_2)\bar\varepsilon - Z_1^*)^2] .
\end{eqnarray}
Therefore, the least-squares estimator is always correctly centred $(\nu_*=0)$ given Assumption~\ref{cond: error distribution}. In Section \ref{ssec: main result}, we give Condition~\ref{cond: a-Huber mean error} under which a general Huber estimator is correctly centred.

\label{thm: dist convergence of huber mean}
Suppose Assumptions \ref{cond: scale function}-\ref{cond: empirical distribution of signal matrix} hold. Further, suppose that the empirical Huber objective satisfies Assumption~\ref{cond: restricted secant inequality} in Section~\ref{ssec: stationary Huber AMP}.  Let $\lim_{n,p\to \infty} {n}/{p} \coloneq \delta >1$, and further let 
\begin{equation} \label{eq: transformed coordinates}
    \check\beta : = \Omega_p^{1/2} \hat \beta , \qquad  \tilde\beta_{0} \coloneq  \Omega_p^{1/2} \beta_0, \qquad  \tilde\gamma_{0} \coloneq  \Omega_p^{1/2} \gamma_0.
\end{equation}
    Then, for any continuous function $\phi: \mathbb R^3 \to \mathbb R$ satisfying the polynomial growth condition with order $2$ (defined in \eqref{eq: polynomial growth}), we have almost surely
    \begin{eqnarray}\label{eq: asymptotic risk Huber estimator}
 \frac{1}{p} \sum_{j =1}^p \phi (\check\beta_j -  \tilde\beta_{0, j} - \nu_* \tilde\gamma_{0, j}, \,  \tilde\beta_{0, j}, \, \tilde\gamma_{0, j} ) {\to} E [\phi (\tau_* G, \bar\beta_0, \bar\gamma_0)],    
    \end{eqnarray}
    where $G\sim N(0,1)$ is independent of $(\bar\beta_0, \bar\gamma_0)$, and $\nu_*, \tau_*^2$ correspond to the solution of \eqref{eq: fixed point state evolution}-\eqref{eq: barSigma*_def}, which is unique.

\label{cor: asymptotic characterization}
Under the setting of Theorem \ref{thm: dist convergence of huber mean}, we have almost surely 
    \begin{eqnarray}\label{eq: asymptotic risk convergence}
            \frac{1}{p} (\hat\beta - \beta_0 - \nu_* \gamma_0)^\top \Omega_p (\hat\beta -  \beta_0 - \nu_* \gamma_0) {\to} \tau_*^2.   
    \end{eqnarray}

\label{prop: state evolution of beta0}
Suppose that Assumptions~\ref{cond: error distribution}--\ref{cond:white_noise_design}, \ref{cond: empirical distribution of signal matrix}, and \ref{cond: existence initialization} hold. Let $\check \beta^{k+1} = \delta b_k B^{k+1}_1$, where the $B^{k+1}_1$ is the Huber AMP iterate in \eqref{eq: Huber_AMP}. Then, for any continuous function $\phi: \mathbb R^3 \to \mathbb R$ satisfying the polynomial growth condition,
\begin{eqnarray}\label{eq: main theorem  result equation}
\frac{1}{p} \sum_{j =1}^p \phi (\check\beta^{k+1}_j - \mu_{k+1} \tilde\beta_{0, j} - \nu_{k+1} \tilde\gamma_{0, j}, \, \tilde\beta_{0, j}, \,  \tilde\gamma_{0, j} ) \stackrel{}{\to} E [\phi (\tau_{k+1} G, \, \bar\beta_0, \,  \bar\gamma_0)],    
\end{eqnarray}
almost surely as $n, p\to \infty$ and $n/p \to \delta$, where $G \sim N(0,1)$ is independent of $(\bar\beta_0, \bar\gamma_0)$.

\label{lem: vanishing increments}
Consider the AMP iteration \eqref{eq: generic AMP algorithm}, with the functions and initialization given by \eqref{eq: gk_fk_Huber_stationary}-\eqref{eq: SE stationary}. For $k \ge 1$, let  $\check\beta^k: = \check B^k_1$ and $R_1^k=\bm Y-\Theta_1^k$.  Then, we almost surely have 
\begin{equation}\label{eq: increment vanish beta}
\lim_{k \to \infty} \lim_{n,p \to \infty}
\frac{1}{p}\|\check\beta^{k+1}-\check\beta^k\|_2^2=0, 
\end{equation}
and
\begin{equation}\label{eq: increment vanish residual}
\lim_{k \to \infty}  \lim_{n,p \to \infty}
\frac{1}{n}\|R_1^{k+1}-R_1^k\|_2^2=0,
\end{equation}
where the limits in $n,p$ are taken with $n/p \to \delta$.

\label{lem: mse convergence Huber and AMP at stationarity}
With the same setting as Lemma \ref{lem: vanishing increments} and under Assumption~\ref{cond: restricted secant inequality}, we almost surely have
\begin{equation} \label{eq: mse convergence Huber and AMP at stationarity}
    \lim_{k \to \infty} \limsup_{p \to \infty} \frac{1}{\sqrt p}\|\check\beta - \check\beta^{k+1}\|_2 = 0,
\end{equation}
where $\check \beta$ is the Huber estimator in whitened coordinates defined in \eqref{eq: minimization whitened coordinate}.

\label{def: wasserstein distance}
    Let $\mathcal P_r(\mathbb R^k)$ denote the set of probability measures on $\mathbb R^k$ with finite $r$th moments for $r \in [1,\infty)$. For $P,Q\in\mathcal P_r(\mathbb R^k)$, define
\[W_r(P,Q)=
\left\{
\inf_{\pi\in\Pi(P,Q)}
\int
\|x-y\|_2^r\,\pi(dx,dy)
\right\}^{1/r},
\]
where $\Pi(P,Q)$ is the set of couplings of $P$ and $Q$.

\label{lem: wasserstein convergence of matrix AMP}
Consider the recursion in \eqref{eq: generic AMP algorithm} for the model in \eqref{eq: data generating process}, with the whitened matrix $\tilde{\bm X}= \bm X \Omega_p^{-1/2}$ satisfying Assumption~\ref{cond:white_noise_design}. Further, assume that Assumptions~\ref{cond: empirical distribution of signal matrix}, \ref{cond: error distribution}, and \ref{cond: existence initialization} hold. Then for each $k \ge 0$,
\begin{align}
    &(\tilde B, \check B^0, \, B^1, \ldots, B^{k+1}) \stackrel{W_2}{\to} 
(\bar B, \bar B^0  , M_B^{1}\bar B + G _B^{1}, \ldots,  M_B^{k+1}\bar B + G _B^{k+1})  \label{eq: wasserstein convergence 1}, \\
 & (\bm\varepsilon, \tilde\Theta, \Theta^0, \Theta^1, \ldots, \Theta^{k}) \stackrel{W_2}{\to} (\bar\varepsilon, Z, Z^0, Z^1, \ldots, Z^{k})  \label{eq: wasserstein convergence 2},
\end{align}
almost surely as $n, p \to \infty$ and $n/p \to \delta$. In the above, for $t=0,\ldots, k$, $G_B^{t+1} \sim N(0, T_B^{t+1})$ is independent of $\bar B$, and  $\begin{pmatrix} Z \\ Z^t \end{pmatrix} \sim N(0, {\bar\Sigma}^t)$, where the matrices 
$M_B^{t+1}, T_B^{t+1}, {\bar\Sigma}^t$ are given by the state evolution recursion in \eqref{eq: state-evolution matrix AMP}-\eqref{eq:Sigmak_update}, with initialization $\bar\Sigma^0$.
Further, for $0 \le s \le s' \le k$, we have
\begin{align}
& E [G_B^{s+1} (G_B^{s'+1})^\top]   = E[h_s(Z, Z^s, \bar\varepsilon) h_{s'}(Z, Z^{s'}, \bar\varepsilon)^\top], \label{eq: GB_covariance} \\

& E [Z^s (Z^{s'})^\top]  = \frac{1}{\delta} E[ f_{s}(M_B^{s} \bar{B} + G_B^{s}) (f_{s'}(M_B^{s'} \bar{B} + G_B^{s'}))^\top].  \label{eq: Gtheta_covariance}
\end{align}
(In \eqref{eq: Gtheta_covariance}, for $s=0$, we take $f_{0}(M_B^{0} \bar{B} + G_B^{0}) \equiv \bar{B}^0$.)

For brevity, we drop the subscripts $*$ throughout the proof. We will assume  that $a <\infty$, as the case of $a=\infty$ (least squares) is covered by Example \ref{example: LS}.
We first show that for any  $(\nu, \tau^2)$, the solution for $b$ in the first equation of \eqref{eq: fixed point state evolution} exists and is unique.  Using \eqref{eq: g_1_derivatives}, this equation can be written as
\begin{align}
\label{eq: FP equation b}
    \frac{1}{b} +1  = \delta \,  \mathbb P( |Z_1 + \sigma(Z_2) \bar\varepsilon - Z_1^*|\le a(1+b)) , 
\end{align}
 where we note from \eqref{eq: barSigma*_def} that the joint law of $(Z_1, Z_2, Z_1^*)$ depends only on $(\nu, \tau^2)$, and not on $b$. For $b \in (0, \infty)$, the left hand side of \eqref{eq: FP equation b} strictly decreases from $\infty$ to $1$, while the right hand side increases from $\delta P( |Z_1 + \sigma(Z_2) \bar\varepsilon - Z_1^*|\le a) \ge 0$ to $\delta$. Therefore, \eqref{eq: FP equation b} has a  unique solution $b(\nu, \tau^2)$  if (and only if) $\delta >1$. Moreover, for any $\tau^2>0$, the right side of \eqref{eq: FP equation b} is continuous in $b$, and therefore the solution $b(\nu, \tau^2)$ is continuous in $(\nu, \tau^2)$.

Writing $b \equiv b(\nu, \tau^2)$, we can express the  set of fixed point equations in \eqref{eq: fixed point state evolution} in terms of  $(\nu, \tau^2)$. Let
$f \equiv (f_1, f_2) :  \mathbb R \times \mathbb R_+ \to \mathbb R \times \mathbb R_+$, where
\begin{align}
    f_1(\nu, \tau^2) & =  \frac{ \delta b }{1+b} \,  E\big[ \, I \big\{ |Z_1 + \sigma(Z_2) \bar\varepsilon - Z_1^*| \le a \big(1+ b \big)  \big\} \, \sigma'(Z_2)\bar\varepsilon \big]  \, ,  \label{eq:f1_def} \\
    f_2(\nu, \tau^2) & =  (\delta b)^2 E\Big[g (Z_1^*,  Z_1 + \sigma(Z_2) \bar\varepsilon ; \, b)^2\Big] .
    \label{eq:f2_def}
\end{align}
We first argue that $f \equiv (f_1, f_2)$ is continuous in both $\nu$ and  $\tau^2$. Indeed, the expectations in \eqref{eq:f1_def}, \eqref{eq:f2_def} are both bounded (by Assumption
\ref{cond: scale function} and \eqref{eq: g_1 function Huber}, respectively), and continuity follows by dominated convergence and the continuity of $b$. 

Next we show that there exists a compact convex set $\mathcal K$ of the form $$\mathcal K \equiv  [-K , \, K] \times [\underline{A}, \, A], $$ such that $f(\nu, \tau^2) \in \mathcal K$ for all $(\nu, \tau^2) \in \mathcal K$.  Recalling that $f$ is continuous on $\mathcal K$, the existence of a fixed point is then guaranteed by Brouwer's fixed point theorem \citep{zeidler1988nonlinear}. 


The constant $K >0$  can be taken to be $\delta E[\bar\varepsilon^2]^{1/2} (E[|\sigma'(Z_2) |^2])^{1/2}$, which is finite by Assumptions~\ref{cond: scale function} and \ref{cond: error distribution}. Then, for $f_1$, it holds by the Cauchy-Schwarz inequality that $|f_1(\nu, \tau^2)| < \delta E[|\sigma'(Z_2)\bar\varepsilon|] 
\leq \delta E[\bar\varepsilon^2]^{1/2}{E[|\sigma'(Z_2)|^2]}^{1/2} = K$. The remainder of the proof consists of showing the existence of constants  $A> \underline{A} >0$, completing the specification of $\mathcal K$. Let 
\begin{align*}
    W= (Z_1 + \sigma(Z_2) \bar\varepsilon - Z_1^*), \quad  \text{and} \quad T_{a(1+b)}(W) = \begin{cases} W, & |W|  \le a(b+1),  \\
    a(b+1) \cdot \text{sgn}(W), & \text{ otherwise}.\end{cases}
\end{align*}
Then, using \eqref{eq: g_1 function Huber} we can  write $f_2$ as 
\begin{align}
\label{eq:f2_T_def}
    f_2(\nu, \tau^2) = \frac{(\delta b)^2}{(1+b)^2} E\left[ T_{a(1+b)}(W)^2 \right]
    =  \frac{E\left[ T_{a(1+b)}(W)^2 \right]}{\mathbb P( |W| \le a(1+b))^2} \, ,
\end{align}
where the last equality uses \eqref{eq: FP equation b}.  Recalling that $(Z_1, Z_2, Z_1^*) \sim N(0, \bar\Sigma^*)$, using the covariance in \eqref{eq: barSigma*_def} we have $$W \stackrel{d}{=} - \nu Z_2 \,  +  \sigma(Z_2) \bar\varepsilon \, +  \frac{\tau}{\sqrt{\delta}} G, \qquad Z_2 \perp G \sim N(0,1).  $$
Denoting $U=- \nu Z_2 \,  +  \sigma(Z_2) \bar\varepsilon$, we claim that 
\begin{align}
\label{eq:Tvar_decomp}
   E\left[ T_{a(1+b)}(W)^2 \right] \le \frac{\tau^2}{\delta} \mathbb P( |W| \le a(1+b)) + E[U^2].
\end{align}
To show \eqref{eq:Tvar_decomp},  consider the conditional second moment
\begin{align}
\label{eq:cond_second_mom_decomp}
    E\left[ T_{a(1+b)}(W)^2 \mid U \right] = \operatorname{var}\Big( T_{a(1+b)}(U + \tau/\sqrt{\delta} \, G) \mid U \Big) + E[T_{a(1+b)}(U + \tau/\sqrt{\delta} \,  G ) \mid U]^2. 
\end{align}
The function $g \mapsto T_{a(1+b)}(U + \tau/\sqrt{\delta} \, g)$ is Lipschitz with (weak) derivative $\frac{\tau}{\sqrt{\delta}}I(|U + \tau/\sqrt{\delta} \, g| \le a(b+1))$. Therefore, by the Gaussian Poincar{\'e} inequality \citep[Theorem 3.20]{boucheron2013concentration},
\begin{align}
\label{eq:var_poincare_bound}
    \operatorname{var}\Big( T_{a(1+b)}(U + \tau/\sqrt{\delta} \, G) \mid U \Big) \le \frac{\tau^2}{\delta} \mathbb P(|U + \tau/\sqrt{\delta} \, G| \le a(1+b)).
\end{align} 
Since $T_{a(1+b)}$ is 1-Lipschitz, so is $\Psi(U) \coloneq  E[T_{a(1+b)}(U + \tau/\sqrt{\delta} \,  G ) \mid U]$, which implies $|\Psi(U) -\Psi(0)| \le |U|$.  Moreover, since $T_{a(1+b)}$ is odd, $\Psi(0)=0$, hence 
\begin{align}
\label{eq:second_mom_T_bound}
  \Psi(U)^2 =  E[T_{a(1+b)}(U + \tau/\sqrt{\delta} \,  G ) \mid U]^2  \le U^2. 
\end{align}
Using  \eqref{eq:var_poincare_bound} and \eqref{eq:second_mom_T_bound} in   \eqref{eq:cond_second_mom_decomp} and taking expectations yields \eqref{eq:Tvar_decomp}. Using \eqref{eq:Tvar_decomp} in \eqref{eq:f2_T_def}, we obtain
\begin{align}
    f_2(\nu, \tau^2) & \le \frac{\tau^2}{\delta \, \mathbb P(|U + \tau/\sqrt{\delta} \, G| \le a(1+b))} \, + \, \frac{E[U^2]}{\mathbb P(|U + \tau/\sqrt{\delta} \, G| \le a(1+b))^2} \nonumber \\
    & =  \tau^2\frac{b}{1+b} \, + \, \frac{E[U^2]}{\mathbb P(|U + \tau/\sqrt{\delta} \, G| \le a(1+b))^2}  \nonumber \\
    & \le \tau^2\frac{b}{1+b} \, + \, \delta^2 E[U^2] = \tau^2 -\frac{1}{1+b}\tau^2 \, + \, \delta^2 E[U^2], \label{eq:f2_bound}
\end{align}
where the first equality follows from \eqref{eq: FP equation b}. Next, we show that $(1+b)$ grows at most linearly in $\tau$, and use it in  \eqref{eq:f2_bound} to obtain $0 <\underline{A} <A$ such that $f_2(\nu, \tau^2) \in [\underline{A}, A]$ for $\tau^2 \in [\underline{A}, A]$ and  $\nu \in [-K, K]$.
Specifically, we show
\begin{align}
\label{eq:b1_bound}
    (1+b) \le \max\left\{ 1+ \frac{2}{\delta-1}, \ \, \frac{1}{a} \sqrt{\frac{2 \delta}{(\delta -1)} \left( \frac{\tau^2}{\delta} + E[U^2]\right)}\right\},
\end{align}
noting that the right hand side is linear in $\tau$. The bound is trivial for $b \le \frac{2}{\delta -1}$. For $b > \frac{2}{\delta -1}$,  from \eqref{eq: FP equation b} we have
\begin{align}
\label{eq:LB_tail_prob}
    P(|W| > a(1+b) ) > \frac{\delta-1}{2 \delta},
\end{align}
and using Chebyshev's inequality,  we have the upper bound
\begin{align}
\label{eq:UB_tail_prob}
   \mathbb P(|W| > a(1+b)) \le \frac{E[W^2]}{a^2(1+b)^2} = \frac{E[U^2] + \frac{\tau^2}{\delta}}{a^2(1+b)^2}.
\end{align}
Combining the bounds in \eqref{eq:LB_tail_prob} and \eqref{eq:UB_tail_prob} yields \eqref{eq:b1_bound}. By \eqref{eq:b1_bound},
\[
  \frac{\tau^2}{1+b} \;\ge\;  \min\Big\{ \tau^2 \frac{(\delta -1)}{(\delta+1)},\; \frac{\tau^2}{\Lambda_2} \Big\}, \qquad \Lambda_2: = \frac{1}{a} \sqrt{\frac{2 \delta}{(\delta -1)} \left( \frac{\tau^2}{\delta} + E[U^2]\right)}.
\]
By the definition of $U$, $E[U^2] = \nu^2 E[Z_2^2] + E[\sigma(Z_2)^2]E[\bar \varepsilon^2] $.
With $K$ chosen as described above, let $\overline{M}^2 \coloneq K^2 E[Z_2^2] + E[\sigma(Z_2)^2]E[\bar\varepsilon^2]$, so that $E[U^2] \le \overline{M}^2$ uniformly over $|\nu|\le K$.  Therefore, for
$|\nu|\le K$ and $\tau^2 \ge  \delta \overline{M}^2$, we have $\Lambda_2  \le \frac{2 \tau}{a \sqrt{\delta -1}}$ and $\tau^2/\Lambda_2\ge \frac{a}{2}\sqrt{\delta-1}\;\tau$. Using this in \eqref{eq:f2_bound}, $f_2(\nu, \tau^2) \le \tau^2$ whenever $| \nu | \le K$ and 
\begin{equation}\label{eq: T choice}
  \tau \;\ge\; \tau_0 \;\coloneq\; \max\left\{ \sqrt{\delta}\,\overline{M}, \;\;
  \delta\,\overline M\sqrt{\frac{\delta+1}{\delta-1}}, \;\;
  \frac{2\delta^2 \overline{M}^2}{a\sqrt{\delta-1}} \right\} .
\end{equation}

We set $A\coloneq \tau_0^2 + \delta^2 \overline{M}^2$, and note from \eqref{eq:f2_bound} that $f_2(\nu, \tau^2) \le A$ for $\tau^2 \le \tau_0^2$. For $\tau^2 \in [\tau_0^2 , A]$, by \eqref{eq: T choice} we have $f_2(\nu, \tau^2) \le \tau^2 \le A$ . To obtain a lower bound $\underline{A}$,  we start from \eqref{eq:f2_T_def}, which implies $f_2(\nu, \tau^2) \ge E[T_{a(1+b)}(W)^2]$. Note that  the map  $b \mapsto T_{a(1+b)}(W)^2$ is non-decreasing in $b$ for each $W$, and from \eqref{eq: FP equation b},  $b \ge \frac{1}{\delta -1}$. Therefore,
\[ f_2(\nu, \tau^2) \ge E[T_{a(1+b)}(W)^2] \ge E[T_{a\delta/(\delta-1)}(W)^2]. \] 
The right side is
bounded below by a constant $\underline{A} > 0$ depending only on $a,\delta$ and the laws of $Z_2,\bar\varepsilon$. Shrinking $\underline{A}$ if necessary so that $A >\underline{A}$ completes the specification of the compact convex set $\mathcal K \equiv  [-K , \, K] \times [\underline{A}, \, A]$ such that $f(\nu, \tau^2) \in \mathcal K$ for all $(\nu, \tau^2) \in \mathcal K$. This completes the proof.

By the definition of $\bar g$ in \eqref{eq: proximal}, for any $(u, y) \in \mathbb R^2$ and $b \in \mathbb R_+$, we have
\begin{eqnarray}\label{eq: proximal estimating equations}
    \partial_1 \ell_a (\bar g (u, y; \, b), y) + \frac{1}{b} (\bar g(u, y; \, b) - u) =0.
\end{eqnarray}

At the fixed point,  by \eqref{eq: Huber_AMP_FP_simple} we have
\begin{eqnarray}\label{eq: X orthogonal to residual}
 {\bm X}^\top g(\Theta^{*}_1, \bm Y ; \, b_*) = (\tilde{\bm X} \Omega_p^{1/2})^\top g(\Theta^{*}_1, \bm Y ; \, b_*) = \Omega_p^{1/2} \tilde{\bm X}^\top g(\Theta^{*}_1, \bm Y ; \, b_*) =  0.   
\end{eqnarray}

Further, by  \eqref{eq: Huber_AMP_FP_simple} and \eqref{eq: effective score}, 
\begin{eqnarray}\label{eq: proximal at stationarity}
  \bar g(\Theta_1^*, \bm Y; \, b_*) = \tilde{\bm X}\check\beta^* = \bm X \hat\beta^* ,
\end{eqnarray}
where we have used the definitions of $\check\beta^* $ and $\hat\beta^*$ in the lemma statement. Therefore,
\begin{align*}
   \sum_{i=1}^n \partial_1 \ell_a(X_i^\top\hat\beta^*, Y_i)X_i &=  \sum_{i=1}^n \partial_1 \ell_a( \bar g(\theta_{1i}^*, Y_i; \, b_*), Y_i) X_i \\
    & = - \sum_{i=1}^n g(\theta_{1i}^*, Y_i; \, b_*) X_i = - \bm X^\top g(\Theta^{*}_1, \bm Y ; \, b_*)  = 0_p,
\end{align*}
where the first equality holds by \eqref{eq: proximal at stationarity}, the second  by \eqref{eq: proximal estimating equations}, and the last by \eqref{eq: X orthogonal to residual}. 

Thus, it holds that
\[
\nabla_\beta \sum_{i=1}^n \ell_a( X_i^\top \beta, Y_i) \Big\vert_{\, \beta = \hat\beta^*} = \sum_{i=1}^n \partial_1 \ell_a(X_i^\top \beta, Y_i)X_i \Big\vert_{\, \beta = \hat\beta^*}  =  0_p,
\]
so convexity of $\ell_a$ implies that $\hat\beta^*$ is a minimizer of \eqref{eq: M-estimator minimization}.

We write
\begin{align}
\label{eq: beta three term split}
    \frac{1}{p}\|\check\beta^{k+1}-\check\beta^k\|_2^2 =
\frac{1}{p}\|\check\beta^{k}\|_2^2 \,  + \,  \frac{1}{p}\|\check\beta^{k+1}\|_2^2 
- 2 \frac{1}{p}(\check\beta^{k})^\top \check\beta^{k+1},  \\

\label{eq: R three term split}
\frac{1}{n}\|R_1^{k+1}-R_1^k\|_2^2 =   
\frac{1}{n}\|\Theta_1^k\|_2^2 \,  + \,  \frac{1}{n}\|\Theta_1^{k+1}\|_2^2 
- 2 \frac{1}{n}(\Theta_1^{k})^\top \Theta_1^{k+1}.
\end{align}
We compute the limiting values for each of the terms on the right using the state evolution result in Lemma \ref{lem: wasserstein convergence of matrix AMP} (and the special case in Proposition \ref{prop: state evolution of beta0}). The limits in the rest of the proof all hold with probability $1$.

For the first two terms in \eqref{eq: beta three term split}, we apply Proposition~\ref{prop: state evolution of beta0} with the test function $\phi: \mathbb R^3 \to \mathbb R$, defined as $\phi(u,v,w) = (u + \mu_{k+1}  v+ \nu_{k+1} w)^2$. This yields
\begin{equation}
\lim_{p \to \infty} \frac{1}{p}\|\check\beta^{k}\|_2^2 = E \left[ (\tau_k G + \mu_{k} \bar \beta_0 + \nu_{k} \bar \gamma_0)^2 \right], \qquad  \lim_{p \to \infty} \frac{1}{p}\|\check\beta^{k+1}\|_2^2 = E \left[ (\tau_{k+1} G + \mu_{k+1} \bar \beta_0 + \nu_{k+1} \bar \gamma_0)^2 \right],
\end{equation}
where $G \sim N(0,1)$ is independent of $(\bar \beta_0, \bar \gamma_0)$.
Using \eqref{eq: coefficient per iteration} and  the stationary functions and state evolution parameters in \eqref{eq: gk_fk_Huber_stationary}-\eqref{eq: SE stationary}, for $k \ge 0$ we have 
\[ \mu_{k} = (\delta b_*) M^*_{B, 11} =1, \qquad \nu_k = (\delta b_*) M^*_{B, 12} = \nu_*, \qquad \tau_k^2 = (\delta b_*)^2 T^*_{B, 11} =\tau^2_*\, . \]
Therefore, 
\begin{equation}
\label{eq: betak norm}
    \lim_{p \to \infty} \frac{1}{p}\|\check\beta^{k}\|_2^2 = E[ (\bar \beta_0 + \nu_{*} \bar \gamma_0)^2] + \tau_*^2, \qquad k \ge 0.
\end{equation}
Similarly, using Lemma \ref{lem: wasserstein convergence of matrix AMP}, we have 
\begin{equation}
\label{eq: thetak norm}
     \lim_{p \to \infty} \, \frac{1}{n}\|\Theta_1^k\|_2^2 = \bar \Sigma^k_{22} = \bar \Sigma^*_{22}, \qquad k \ge 0,
\end{equation}
where the last equality holds due to the stationary state evolution update \eqref{eq: SE stationary}.

We now address the cross terms in \eqref{eq: beta three term split} and \eqref{eq: R three term split}.
Next, recalling that $\check\beta^{k} = (\delta b_*) B^k_1$ and using  \eqref{eq: wasserstein convergence 1} (and Definition \ref{def: wasserstein}), we have
\begin{equation}
\label{eq: Bk_Bk1}
\begin{split}
        \frac{1}{p}(\check\beta^{k})^\top \check\beta^{k+1} & = (\delta b_*)^2 \frac{1}{p} \sum_{j=1}^p  B^k_{1,j}  B^{k+1}_{1,j} \\
        & \stackrel{p \to \infty}{\longrightarrow} \, (\delta b_*)^2 \left(  E[ (M^k_{B, 11} \bar \beta_0 + M^k_{B, 12} \bar \gamma_0 ) (M^{k+1}_{B, 11} \bar \beta_0 + M^{k+1}_{B, 12} \bar \gamma_0 )] \,  +  \, E[G^k_{B,1} G^{k+1}_{B,1}] \right) \\

        & = E[ (\bar \beta_0 + \nu_{*} \bar \gamma_0)^2] \, + \, 
        (\delta b_*)^2 E[G^k_{B,1} G^{k+1}_{B,1}],
\end{split}
\end{equation}
where the last line again holds due to \eqref{eq: SE stationary}. For the cross-term in \eqref{eq: R three term split}, using \eqref{eq: Gtheta_covariance} we have 
\begin{equation}
\label{eq: Zk_Zk1}
\begin{split}
    \lim_{n \to \infty} \frac{1}{n}(\Theta_1^{k})^\top \Theta_1^{k+1} & =    E[Z^k_1 Z^{k+1}_1 ] \\
    & = \frac{1}{\delta }(\delta b_*)^2   E[ (M^k_{B, 11} \bar \beta_0 + M^k_{B, 12} \bar \gamma_0  + G^k_{B,1}) (M^{k+1}_{B, 11} \bar \beta_0 + M^{k+1}_{B, 12} \bar \gamma_0 + G^{k+1}_{B,1} )] \\
    & = \frac{1}{\delta} \left( E[ (\bar \beta_0 + \nu_{*} \bar \gamma_0)^2]  \, + \, 
        (\delta b_*)^2 E[G^k_{B,1} G^{k+1}_{B,1}] \right).
    \end{split}
\end{equation}
From \eqref{eq: GB_covariance} and recalling that $h_k(s, w, v) =  g_k (w, q(s, v))$, we have 
\begin{equation}
\label{eq: GB_k_k1}
\begin{split}
        E[G^k_{B,1} G^{k+1}_{B,1}] & = E[ h_{k-1, 1}(Z, Z^{k-1} , \bar \varepsilon)
        h_{k, 1}(Z, Z^{k} , \bar \varepsilon)] \\
        & = E[g(Z_1^{k-1},   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_*) g(Z_1^{k},   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_*)],
\end{split}
\end{equation}
where we used the definition of $g_k$ in \eqref{eq: gk_fk_Huber_stationary}.  

The equations \eqref{eq: Zk_Zk1} and \eqref{eq: GB_k_k1} together define a recursion in the one-step covariance $E[G^k_{B,1} G^{k+1}_{B,1}]$, for $k \ge 0$.
From  \eqref{eq: SE stationary}, we know that marginally $G^k_{B,1} \sim N(0, T^*_{B,11})$ for  all $k \ge 0$, where  $T^*_{B,11}=  \tau_*^2/(\delta b_*)^2$.  Using the initialization \eqref{eq: stationary init} together with Assumption \ref{cond: existence initialization}, we have $E[G^0_{B,1} G^{k}_{B,1}] = 0$ for $k \ge 1$. Defining the correlation coefficient 
$$q_k \coloneq \frac{E[G^k_{B,1} G^{k+1}_{B,1}]}{T^*_{B,11}}  =  \frac{E[G^k_{B,1} G^{k+1}_{B,1}] (\delta b_*)^2}{\tau_*^2} ,$$
we now show that $\lim_{k \to \infty} q_k =1$. Using this in \eqref{eq: Bk_Bk1} and \eqref{eq: Zk_Zk1} and combining with the limits in \eqref{eq: betak norm}-\eqref{eq: thetak norm} yields the lemma.

To show $q_k \to 1$, we begin by writing the  one-step recursion from \eqref{eq: Zk_Zk1} and \eqref{eq: GB_k_k1} as $q_k =H(q_{k-1})$, for $k \ge 1$, where 
\begin{equation}
\label{eq: Hdef}
\begin{split}
    H(q) = 
    (T^*_{B,11})^{-1}E[g(\hat Z_1,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_*) g(\check Z_1,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_*)], \quad q \in [0,1].
\end{split}
\end{equation}
Here, the expectation is with respect to the following distribution:   $(Z_1, Z_2, \hat Z_1, \check Z_1 )^\top$ are jointly Gaussian with
 $(Z_1, Z_2, \hat Z_1)^\top \stackrel{\rm d}{=} (Z_1, Z_2, \check Z_1)^\top  \sim N(0, \bar{\Sigma}^*)$, and 
 $ E[ \hat Z_1 \check Z_1 ] = \frac{1}{\delta} \left( E[ (\bar \beta_0 + \nu_{*} \bar \gamma_0)^2]  \, + \, 
        q \tau_*^2  \right)$. 
The recursion is initialized with $q_0=0$.  Using the definition of $\bar \Sigma^*$ from \eqref{eq: barSigma*_def} and properties of jointly Gaussian random vectors, we can express $\hat Z_1, \check Z_1$ as:
\begin{align}
\label{eq: hat check exp}
    \hat Z_1 = \bar{M} Z + \,  \bar{\zeta} G_1, \qquad \check Z_1 = \bar{M} Z + \, \bar{\zeta} G_2,
\end{align}
where 
\begin{align}
\label{eq: hat check coeffs}
Z= \begin{pmatrix}
        Z_1 \\
        Z_2
    \end{pmatrix}, \quad 
    \bar{M}= (\bar \Sigma^*_{12})^\top (\bar\Sigma^*_{11})^{-1}, \quad 
    \bar{\zeta}^2 = \bar \Sigma^*_{22}  \, -  \, (\bar \Sigma^*_{12})^\top (\bar\Sigma^*_{11})^{-1} \bar \Sigma^*_{12}, \quad (G_1, G_2)^\top \sim N\left( 0, \begin{pmatrix}
        1 & q \\
        q &  1
    \end{pmatrix} \right),
\end{align}
and $(G_1, G_2)$ are independent of $Z$.

Similar to the proof strategy of \citet[Lemma~6.9]{donoho2016high}, we prove the following three claims:
\begin{enumerate}
    \item[(i)]   $|H(q)| \le H(1)=1$ for $q \in [0,1]$; 
    \item[(ii)] $H(q)$ is  strictly increasing for $q \in [0,1]$;
    \item[(iii)] $H(q)$ is convex for $q \in [0,1]$.
\end{enumerate}

To prove $(\rm i)$, we observe that at $q=1$, $H(1) =  (T^*_{B,11})^{-1} E[g(Z_1^*,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_*)^2]$, which equals $1$, from the definition of $T^*_{B,11}$ in \eqref{eq: state evolution FP MT}. The inequality $|H(q)| \le H(1)$ for $q \in [0,1]$ follows from Cauchy-Schwarz. For $(\rm ii)$ and $(\rm iii)$, we use the same argument as  \citet[Lemma~C.1]{bayati2012lasso} and \citet[Appendix~3.2]{donoho2016high}.  
Using \eqref{eq: hat check exp}-\eqref{eq: hat check coeffs},  we define
\begin{align*}
    &h_{(Z, \bar\varepsilon)} (z) = g\left(\bar M Z + \bar \zeta z, \,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_* \right),
\end{align*}
and write
\begin{align}
\label{eq: mcH def}
    H(q) = (T^*_{B,11})^{-1}E[\mathcal H (q; \, Z, \bar\varepsilon)], \qquad \mathcal H (q; \, Z, \bar\varepsilon) \coloneq E_q[ h_{(Z, \bar\varepsilon)} (G_1) h_{(Z, \bar\varepsilon)} (G_2) \mid Z, \bar \varepsilon],
\end{align}     where $E_q$ denotes the expectation with $(G_1, G_2)$ distributed as specified in \eqref{eq: hat check coeffs}. Letting $(X_t)_{t\ge 0}$ denote the standard Ornstein-Uhlenbeck process with covariance $E[X_0 X_t] = e^{-t}$, we have 
\[
\mathcal H (q; \, Z, \bar\varepsilon) = E[h_{(Z, \bar\varepsilon)} (X_0) h_{(Z, \bar\varepsilon)} (X_t)]\vert_{t = \log(1/q) },
\]
where the expectation is with respect to $X$. We now express $h_{(Z, \bar\varepsilon)}(\cdot) $ using the Hermite orthonormal basis $\{\varphi_l(\cdot) \}_{l\ge 0}$, and write $h_{(Z, \bar\varepsilon)} (X_0)= \sum_{l} c_l(Z, \bar\varepsilon) \varphi_l(X_0)$, where $c_l(Z, \bar\varepsilon) = E [h_{(Z, \bar\varepsilon)} (X_0) \varphi_l(X_0)]$, with the expectation taken over $X_0 \sim N(0,1)$. We recall that the Hermite polynomials $\varphi_l(\cdot)$ are eigenfunctions of the operator $P_t$ defined by $P_t f (x) = E[ f(X_t) \mid X_0 = x]$. Indeed, for $l \ge 0$, it holds that $P_t \varphi_l(x) = e^{-tl} \varphi_l(x)$ \citep{bakry2014analysis}. We then have the following spectral representation:
\begin{align*}
\mathcal H (q; \, Z, \bar\varepsilon) & = E [h_{(Z, \bar\varepsilon)} (X_0) \cdot P_t h_{(Z, \bar\varepsilon)} (X_0)]\vert_{t = \log (1/q)} \qquad &\\
  &=  E [\sum_{l = 0}^\infty c_l \varphi_l(X_0) P_t (\sum_{l' = 0}^\infty c_{l'}
  \varphi_{l'}(X_0))  ]\vert_{t = \log (1/q)}\\ 
 &=E [\sum_{l = 0}^\infty c_l \varphi_l(X_0) \sum_{l' = 0}^\infty c_{l'}  e^{-tl'}\varphi_{l'}(X_0)  ]\vert_{t = \log (1/q)} \\
  &= \sum_{l = 0}^\infty c_l^2 e^{-l \log(1/q) } = \sum_{l = 0}^\infty c_l^2 q^l.
\end{align*}
Claims $(\rm ii)$ and $(\rm iii)$ then follow by noting that $H(q) =  (T^*_{B,11})^{-1}\sum_{l = 0}^\infty E[c_l(Z, \bar\varepsilon)^2 ]q^l$, and  from the definition of $g$, it follows that $E[c_l(Z, \bar\varepsilon)^2 ] >0$ for at least one $l \ge 1$.

By convexity of $H(\cdot)$, we have 
\begin{equation}
\label{eq: Hq supporting line ineq}
    H(q) \ge H(1) - H'(1)(1-q) = 1 - H'(1)(1-q), \qquad q \in [0,1].
\end{equation} 
The proof is completed by showing that $0< H'(1) < 1$, which implies $H(q) > q$ for $q \in [0,1)$. Indeed, from \eqref{eq: mcH def} and using Price's theorem \citep{prices_theorem}, we obtain
\begin{align*}
    H'(q)  &  = (T^*_{B,11})^{-1} E \left[ E_q[ h'_{(Z, \bar\varepsilon)} (G_1) h'_{(Z, \bar\varepsilon)} (G_2) \mid Z, \bar \varepsilon] \right] \\

    & = (T^*_{B,11})^{-1} \bar{\zeta}^2 E \left[ E_q[ \partial_1 g\left(\bar M Z + \bar \zeta G_1, \,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_* \right) \partial_1 g\left(\bar M Z + \bar \zeta G_2, \,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_* \right) \mid Z, \bar \varepsilon]    \right],
\end{align*}
where the second equality follows from the definition of $h_{(Z, \bar\varepsilon)}$. Taking $q \to 1$, we obtain
\begin{equation*}
    \begin{split}
          H'(1) & =  (T^*_{B,11})^{-1} \bar{\zeta}^2E[\partial_1 g\left(\bar M Z + \bar \zeta G_2, \,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_* \right)^2 ] \nonumber  \\

  & = (T^*_{B,11})^{-1} \bar{\zeta}^2 \frac{1}{1+b_*}E[-\partial_1 g\left(\bar M Z + \bar \zeta G_2, \,   Z_1 + \sigma(Z_2) \bar\varepsilon; \, b_* \right) ] \\

  & = (T^*_{B,11})^{-1} \bar{\zeta}^2 \frac{1}{(1+b_*)(\delta b_*)} \\  & = \frac{(\delta b_*) \bar{\zeta}^2}{(1+b_*) \tau_*^2}= \frac{b_*}{1+b_*}. 
    \end{split}
\end{equation*}
 The second equality above follows from \eqref{eq: g_1_derivatives}, noting that $(\partial_1 g)^2 = \frac{-1}{1+ b_*} \partial_1 g$; the third equality uses $\partial_1 g = -\partial_2 g$ and the definition of $b_*$ in \eqref{eq: fixed point state evolution}; the fourth equality uses  $\tau_*^2=T^*_{B,11} (\delta b_*)^2$; finally, the fifth holds since $\bar \zeta^2 = {\tau_*^2}/{\delta}$, which can be verified by direct calculation using the expressions for $\bar \Sigma_{12}^*$ and $\bar \Sigma_{22}^*$ in \eqref{eq: barSigma*_def}.

Since $b_* >0$, we have $H'(1) <1$, and thus by \eqref{eq: Hq supporting line ineq}, $H(q) > q$ for $q \in [0,1)$. Recalling from $(\rm i)$ that $H(q)$ is bounded,  monotone convergence implies $\lim_{k \to \infty}q_k =1$, which completes the proof.

We first show $\lim_{\eta \to 0} \delta q_*(\eta) > 1 $. 
By the first equation of \eqref{eq: fixed point state evolution} and $g$ for Huber loss in \eqref{eq: g_1_derivatives}, for $b_* >0$, it holds that, 
\begin{eqnarray*}
    \lim_{\eta \to 0}  q_* (\eta) = P(|Z_1 + \sigma(Z_2)\bar\varepsilon - Z_1^* | < a(1 + b_*) ) = \delta^{-1}(1 + b_* ) /b_* =\delta^{-1}( 1 + b_*^{-1} )>  \delta^{-1}.
\end{eqnarray*}
Let $R_1^{k+1} = \bm Y - \Theta_1^{k+1}$ be as defined in Lemma~\ref{lem: vanishing increments} with components denoted by $R_{1,i}^{k+1}$. Then, using the Huber AMP update  in \eqref{eq: Huber_AMP} and recalling that $b_k = b_*$ for $k \ge 0$, we have
\begin{eqnarray}
 R_1^{k+1}
= \bm Y- \Theta_1^{k+1} 
= \bm Y-  \tilde{\bm X}\check\beta^{k+1}
+
b_* g(\Theta_1^k,\bm Y; b_*). \label{eq: prop proof R1 1}
\end{eqnarray}

Further, by \eqref{eq: effective score} 
\begin{align}\label{eq: prop proof proximal expansion}
\bar g(\Theta_1^k, \bm Y; b_*)
& =\Theta_1^k+b_* g(\Theta_1^k, \bm Y; b_*) & \nonumber
\\&=
\bm Y-R_1^k+b_* g(\Theta_1^k, \bm Y; b_*) 
= 
R_1^{k+1}-R_1^k + \tilde{\bm X}\check\beta^{k+1} \, ,
\end{align}
where the third equality uses \eqref{eq: prop proof R1 1}. 
Then, the ordinary residual can be expressed as
\begin{eqnarray}\label{eq: inlier residual expression 1}
\bm Y - \tilde{\bm X}\check\beta^{k+1} = (\bm Y - \bar g(\Theta_1^k, \bm Y; b_*) )+ (R_1^{k+1} - R_1^k) .   
\end{eqnarray}
For $i \in \{1, \ldots, n\}$, for the components satisfying $ |R_{1,i}^k| < (a- 2\eta) (1 + b_*)$, by \eqref{eq: effective score} and \eqref{eq: g_1 function Huber}, it follows that 
\begin{eqnarray}
| Y_i - \bar g(\Theta_{1i}^k, Y_i; b_*) | = |\frac{Y_i - \Theta_{1i}^{k}}{1 + b_*}| = 
   | \frac{R_{1,i}^k}{1 + b_*} |< (a-2\eta),
\end{eqnarray}
Thus, $| Y_i - \bar g(\Theta_{1i}^k, Y_i; b_*) | < (a- 2\eta)$ if $|R_{1,i}^k| <(a - 2\eta) (1 + b_*)$. 
Denoting $A_i \coloneq \{ |Y_i - \bar g(\Theta_{1i}^k, Y_i; b_*)| < (a- 2\eta) \}$ and $B_i \coloneq \{ |R_{1, i}^{k+1} - R_{1, i}^k | > \eta  \}$, it holds that 
\begin{align}\label{eq: inlier indicator inequality}
    I\{ | Y_i - \tilde X_i^\top \check\beta^{k+1} | <(a - \eta)\} &  \geq I\{ A_i \backslash B_i \}  \nonumber \\
    & \ge I\{ A_i\} - I\{B_i\} \ge I\{|R_{1,i}^k | < (a - 2\eta) (1 + b_*) \} -I\{B_i\} .
\end{align}
The second term, with probability 1, satisfies
\begin{eqnarray}\label{eq: inliear second term vanish}
\frac{1}{n}\sum_{i=1}^n I\left\{ |R_{1, i}^{k+1} - R_{1, i}^k| > \eta \right\}  \leq \frac{1}{\eta^2} \frac1n\|R_{1}^{k+1} - R_1^k\|_2^2 \stackrel{k\to\infty}{\to} 0 ,
\end{eqnarray}
where 
the inequality holds by Markov's inequality, and the convergence result is by \eqref{eq: increment vanish residual}.

By \eqref{eq: inlier indicator inequality} and \eqref{eq: inliear second term vanish}, we obtain
\begin{eqnarray}
\lefteqn{\lim\inf_{n,p\to \infty}q_k (\eta) = \frac{1}{n} \sum_{i=1}^n I\{ |Y_i - \tilde X_i^\top \check\beta^{k+1} | < (a - \eta)\}} &&\\
&\ge& \lim\inf_{n,p\to \infty}\frac{1}{n} \sum_{i=1}^n I\{ |R_{1,i}^k| <(a- 2\eta)(1 + b_*) \} - \lim\sup_{n,p\to \infty}\frac{1}{n}\sum_{i=1}^n I\{ |R_{1, i}^{k+1} - R_{1, i}^k| > \eta\}  \nonumber\\
&\ge &
\mathbb P(|Z_1 + \sigma(Z_2)\bar\varepsilon - Z_1^k| < (a - 2\eta ) (1 + b_*) ) -  
\lim_{n, p \to\infty}\frac{1}{\eta^2} \frac1n\|R_{1}^{k+1} - R_1^k\|_2^2 \nonumber \\
& \stackrel{k \to \infty}{\to}&  \mathbb P(|Z_1 + \sigma(Z_2)\bar\varepsilon - Z_1^*| < (a - 2\eta ) (1 + b_*) ) = q_*(\eta)  \nonumber,
\end{eqnarray}
where the convergence holds almost surely by Lemma~\ref{lem: wasserstein convergence of matrix AMP}.

Denote the objective in \eqref{eq: minimization whitened coordinate} and its gradient by
\begin{eqnarray}\label{eq: gradient definition}
  L_n(\beta)
= \sum_{i=1}^n \ell_a( \tilde X_i^\top \beta, Y_i), \qquad \qquad \nabla_\beta L_n(\beta)
=  \tilde{\bm X}^{\top}\partial_1\ell_a( \tilde{\bm X} \beta, \bm Y),
\end{eqnarray}
where $\partial_1\ell_a(\tilde{\bm X} \beta, \bm Y)$ is applied row-wise. Thus, $\check\beta$ is the minimizer of $L_n$.  By \eqref{eq: proximal estimating equations} and \eqref{eq: effective score},
\begin{eqnarray}\label{eq: prop proof proximal equivalence}
    \partial_1\ell_a(\bar g(u,y; b_*),y)
=
-g(u,y; b_*).
\end{eqnarray}

Recall that $R_1^{k+1} = \bm Y - \Theta_1^{k+1}$ is defined in Lemma~\ref{lem: vanishing increments} and $b_k = b_*$ for $k \ge 0$. Consider the second line of  the Huber AMP update \eqref{eq: Huber_AMP}. Recalling the stationarity of the state evolution and the fact that $\bar C_{11}^k = E[\partial_1 g(Z_1^*, \,  Z_1 + \sigma(Z_2) \bar\varepsilon; b_*)] = - (\delta b_* )^{-1}$,
we have
\begin{eqnarray}\label{eq: prop proof R1 2}
\check\beta^{k+1}-\check\beta^k
= \delta b_*
\tilde{\bm X}^{\top}g(\Theta_1^k, \bm Y; b_k).
\end{eqnarray}

Using the gradient expression in  \eqref{eq: gradient definition}, we have 
\begin{align}
& \frac{1}{\sqrt p}
\|\nabla_\beta L_n(\check\beta^{k+1})\|_2 = 
\frac{1}{\sqrt p}\|- \tilde{\bm X}^{\top}\partial_1\ell_a( \tilde{\bm X} \check\beta^{k+1},\bm Y) \|_2 \nonumber  \\
&= \frac{1}{\sqrt p}\|-  \tilde{\bm X}^{\top}\partial_1\ell_a( \tilde{\bm X} \check\beta^{k+1},\bm Y) +  \tilde{\bm X}^{\top}\partial_1\ell_a( \bar g(\Theta_1^k,\bm Y; b_k), \bm Y) -  \tilde{\bm X}^{\top}\partial_1\ell_a( \bar g(\Theta_1^k,\bm Y; b_k), \bm Y)\|_2
\nonumber
\\
&\leq \frac{1}{\sqrt p}\|\tilde{\bm X}\|_{\mathrm{op}} \|  \bar g(\Theta_1^k,\bm Y ; b_k)- \tilde{\bm X}\check\beta^{k+1}\|_2
 + 
 \frac{1}{\sqrt{p}}\|\tilde{\bm X}^{\top}\partial_1\ell_a( \bar g(\Theta_1^k,\bm Y; b_k), \bm Y)\|_2
 \nonumber
 \\
&\leq
\|\tilde{\bm X}\|_{\mathrm{op}}\sqrt{\frac{n}{p}}
\frac{\|R_1^{k+1}-R_1^k\|_2}{\sqrt n}
 + (\delta b_*)^{-1} \frac{\|\check\beta^{k+1}-\check\beta^k\|_2}{\sqrt{p}}
 ,
\label{eq: gradient control no psi}
\end{align}
where the first inequality uses the triangle inequality and the fact that $\partial_1 \ell_a$ is 1-Lipschitz in the first argument. The first term in the second inequality uses \eqref{eq: prop proof proximal expansion}, while the second term uses \eqref{eq: prop proof R1 2}.
By Lemma~\ref{lem: vanishing increments}, with probability one, we have 
\begin{eqnarray*}
 &&\lim_{k\to\infty}\lim_{n,p\to\infty}
\frac{1}{p}
\|\check\beta^{k+1}-\check\beta^k\|_2^2
=
0, \\
&&
\lim_{k\to\infty}\lim_{n,p\to\infty}
\frac{1}{n}
\|R_1^{k+1}-R_1^k\|_2^2
=
0.    
\end{eqnarray*}
Since  $\lim\sup_{n\to \infty}\|\tilde{\bm X}\|_{\rm op}=O(1)$ almost surely and $b_* >0$,
\eqref{eq: gradient control no psi} yields almost surely
\begin{equation}
\label{eq: lemma 3 gradient as to 0}
\lim_{k\to\infty}\limsup_{p\to\infty}
\frac{1}{\sqrt p}
\|\nabla_\beta L_n(\check\beta^{k+1})\|_2
=0.
\end{equation}

By Assumption~\ref{cond: restricted secant inequality} and \eqref{eq: lemma 3 gradient as to 0}, for sufficiently large $k$ and $n, p$ and $c_0 \in (0, \underline c)$ we have 
\begin{eqnarray}\label{eq: lemma 3 local gradient bound}
\kappa(\rho) \ge c_0, \qquad \qquad \|\nabla_\beta  L_n(\check\beta^{k+1})\|_2 < c_0 \rho \sqrt{p} .    
\end{eqnarray}

We first show by contradiction that any minimizer $\check\beta$ of $L_n$ satisfies 
$\|\check\beta - \check\beta^{k+1}\|_2 \leq \rho\sqrt{p}$. Assume $\|\check\beta - \check\beta^{k+1}\|_2 >\rho\sqrt{p}$, and define the unit vector $d=\frac{\check\beta - \check\beta^{k+1}}{\|\check\beta - \check\beta^{k+1}\|_2}$ and the boundary point $u = \check\beta^{k+1} + \rho\sqrt{p}d$.

By Assumption~\ref{cond: restricted secant inequality}, it holds that 
\begin{eqnarray}\label{eq: gradient inequality}
\rho \sqrt{p} d^\top ( \nabla_\beta L_n(u ) -\nabla_\beta L_n (\check\beta^{k+1})) & = \langle \nabla_\beta L_n (u ) -\nabla_\beta L_n(\check\beta^{k+1}), u - \check\beta^{k+1} \rangle \\ & \ge \kappa(\rho) \| u - \check\beta^{k+1}\|_2^2 \ge c_0 (\rho\sqrt{p})^2. \nonumber
\end{eqnarray}
Thus, \begin{eqnarray}\label{eq: gradient at boundary}
d^\top \nabla_\beta L_n(u ) \ge d^\top \nabla_\beta L_n(\check\beta^{k+1})  + c_0 \rho\sqrt{p} \ge c_0 \rho\sqrt{p} - \| \nabla_\beta L_n(\check\beta^{k+1}) \|_2 > 0,    
\end{eqnarray}
where the first inequality holds by \eqref{eq: gradient inequality}, the second by Cauchy--Schwarz inequality, and the last is by \eqref{eq: lemma 3 local gradient bound}.
Recall that $u$ is the boundary point along the ray from $\check\beta^{k+1}$ to $\check\beta$. Since $\|\check\beta - \check\beta^{k+1}\|_2 > \rho \sqrt{p}$, $\check\beta$ lies beyond $u$ on this ray. Since $L_n$ is convex, its directional derivative along $d$ is nondecreasing as we move away from $\check\beta^{k+1}$ along this ray. Hence, $d^\top\nabla L_n(\check\beta)
\geq d^\top\nabla L_n( u)$ for $\check\beta$ satisfying $\|\check\beta - \check\beta^{k+1}\|_2 > \rho \sqrt p$.
Since $\check\beta$ is a minimizer, $\nabla L_n(\check\beta) = 0$. Because $\|d\|_2=1$, by the Cauchy--Schwarz inequality, it holds that
\[
0 = d^\top\nabla L_n(\check\beta) \ge d^\top\nabla_\beta L_n( u)
> 0,
\]
a contradiction and the last inequality is by \eqref{eq: gradient at boundary}. Hence any minimizer  $\check \beta$ satisfies $\|\check\beta - \check\beta^{k+1}\|_2 \leq \rho\sqrt{p}$, i.e. it lies inside the ball of Assumption \ref{cond: restricted secant inequality}.

Taking $h= \check\beta - \check\beta^{k+1}$ in Assumption \ref{cond: restricted secant inequality}, we obtain that the following holds almost surely,  
\begin{eqnarray*}
\lim_{k\to\infty}\limsup_{p\to\infty}
\frac{
\|\check\beta^{k+1}-\check\beta\|_2
}{\sqrt p}
\leq
